import assert from "node:assert/strict";

const METHOD_INFO = {
  GET: { safe: true, idempotent: true },
  HEAD: { safe: true, idempotent: true },
  PUT: { safe: false, idempotent: true },
  DELETE: { safe: false, idempotent: true },
  POST: { safe: false, idempotent: false },
  PATCH: { safe: false, idempotent: false },
};

function describeMethod(method) {
  const info = METHOD_INFO[method.toUpperCase()];
  if (!info) return { safe: false, idempotent: false, unknown: true };
  return { ...info, unknown: false };
}

// A minimal resource handler: correct method semantics produce correct statuses.
function route(store, method, key, value) {
  switch (method) {
    case "GET":
      return key in store ? { status: 200, body: store[key] } : { status: 404 };
    case "PUT": {
      const existed = key in store;
      store[key] = value;
      return { status: existed ? 200 : 201 };
    }
    case "DELETE":
      if (key in store) { delete store[key]; return { status: 204 }; }
      return { status: 404 };
    default:
      return { status: 405, allow: "GET, PUT, DELETE" };
  }
}

const store = {};
assert.deepEqual(route(store, "PUT", "doc-1", "v1"), { status: 201 });
route(store, "PUT", "doc-1", "v1");
route(store, "PUT", "doc-1", "v1");
assert.equal(store["doc-1"], "v1");
assert.deepEqual(route(store, "GET", "doc-1"), { status: 200, body: "v1" });
assert.equal(route(store, "GET", "missing").status, 404);
assert.deepEqual(route(store, "DELETE", "doc-1"), { status: 204 });
assert.equal(route(store, "DELETE", "doc-1").status, 404);
assert.equal(route(store, "POST", "doc-1").status, 405);
assert.equal(describeMethod("get").safe, true);
assert.equal(describeMethod("PATCH").idempotent, false);
console.log("GET safe:", describeMethod("GET").safe, "| PUT idempotent:", describeMethod("put").idempotent);
console.log("POST idempotent:", describeMethod("POST").idempotent, "| PATCH idempotent:", describeMethod("PATCH").idempotent);
console.log("405 Allow:", route(store, "POST", "doc-1").allow);

