import assert from "node:assert/strict";

const todos = Array.from({ length: 12 }, (_, i) => ({ id: i + 1, title: `Task ${i + 1}` }));

function parseRoute(url) {
  const { pathname, searchParams } = new URL(url);
  const parts = pathname.split("/").filter(Boolean);
  if (parts[0] !== "v1") return { error: "missing-version" };
  if (parts[1] !== "todos") return { error: "unknown-resource" };
  const page = Math.max(1, Number(searchParams.get("page") ?? 1) || 1);
  const limit = Math.min(50, Math.max(1, Number(searchParams.get("limit") ?? 10) || 1));
  return { resource: "todos", page, limit };
}

function listTodos(url) {
  const route = parseRoute(url);
  if (route.error) return { status: 400, error: route.error };
  const start = (route.page - 1) * route.limit;
  return {
    status: 200,
    page: route.page,
    total: todos.length,
    items: todos.slice(start, start + route.limit).map(t => t.id),
  };
}

assert.equal(parseRoute("https://api.test/tasks").error, "missing-version");
assert.equal(parseRoute("https://api.test/v1/users").error, "unknown-resource");
assert.equal(parseRoute("https://api.test/v1/todos?limit=999").limit, 50);
const first = listTodos("https://api.test/v1/todos?limit=5");
const second = listTodos("https://api.test/v1/todos?page=3&limit=5");
assert.equal(listTodos("https://api.test/v1/todos?page=9&limit=5").items.length, 0);
assert.equal(first.items.length, 5);
assert.equal(second.items.length, 2);
console.log(JSON.stringify(first));
console.log(JSON.stringify(second));

