import assert from "node:assert/strict";

const CREATE_PROFILE = {
  name: { type: "string", min: 2, max: 40 },
  age: { type: "number", min: 13, max: 120, integer: true },
  website: { type: "url", optional: true },
};

function validate(schema, input) {
  const errors = [];
  for (const [field, rule] of Object.entries(schema)) {
    const value = input[field];
    if (value === undefined) {
      if (!rule.optional) errors.push({ field, code: "required" });
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") { errors.push({ field, code: "type", expected: "string" }); continue; }
      if (value.trim().length < rule.min || value.trim().length > rule.max) errors.push({ field, code: "length", min: rule.min, max: rule.max });
    } else if (rule.type === "number") {
      if (typeof value !== "number" || !Number.isFinite(value)) { errors.push({ field, code: "type", expected: "number" }); continue; }
      if (rule.integer && !Number.isInteger(value)) errors.push({ field, code: "integer" });
      else if (value < rule.min || value > rule.max) errors.push({ field, code: "range", min: rule.min, max: rule.max });
    } else if (rule.type === "url") {
      if (typeof value !== "string" || !value.startsWith("https://")) errors.push({ field, code: "format", expected: "https-url" });
    }
  }
  for (const field of Object.keys(input)) {
    if (!Object.hasOwn(schema, field)) errors.push({ field, code: "unknown-field" });
  }
  return { valid: errors.length === 0, errors };
}

const clean = validate(CREATE_PROFILE, { name: "  Munir ", age: 20 });
assert.deepEqual(clean, { valid: true, errors: [] });
const bad = validate(CREATE_PROFILE, { name: "A", age: "twenty", website: "http://x.test", role: "admin" });
assert.equal(bad.valid, false);
assert.equal(bad.errors.length, 4);
console.log(clean.valid);
console.log(JSON.stringify(bad.errors));

