import assert from "node:assert/strict";

class AppError extends Error {
  constructor(status, code, message) {
    super(message);
    this.name = "AppError";
    this.status = status;
    this.code = code;
  }
}
class ValidationError extends AppError {
  constructor(details) { super(400, "validation_failed", "Invalid input"); this.details = details; }
}
class NotFoundError extends AppError {
  constructor() { super(404, "not_found", "Resource not found"); }
}

// Centralized handler: expected errors expose a stable code; unexpected errors stay opaque.
function handle(error, log) {
  if (error instanceof AppError) {
    const body = { error: error.code };
    if (error.details) body.details = error.details;
    return { status: error.status, body };
  }
  log(error);
  return { status: 500, body: { error: "internal_error" } };
}

const log = [];
const fakeLog = error => log.push({ name: error.name, message: error.message });

const dbFailure = new Error("ECONNREFUSED 10.0.0.4:5432");
const result1 = handle(dbFailure, fakeLog);
assert.deepEqual(result1, { status: 500, body: { error: "internal_error" } });
assert.match(log[0].message, /ECONNREFUSED/);

const result2 = handle(new ValidationError([{ field: "title", code: "length" }]), fakeLog);
assert.deepEqual(result2, { status: 400, body: { error: "validation_failed", details: [{ field: "title", code: "length" }] } });

const result3 = handle(new NotFoundError(), fakeLog);
assert.deepEqual(result3, { status: 404, body: { error: "not_found" } });
assert.equal(log.length, 1);
