import assert from "node:assert/strict";
import { scryptSync, timingSafeEqual } from "node:crypto";

function hashPassword(password, saltHex) {
  const salt = Buffer.from(saltHex, "hex");
  const derived = scryptSync(password, salt, 32, { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 });
  return `scrypt$16384$${saltHex}$${derived.toString("hex")}`;
}

function verifyPassword(password, stored) {
  const [scheme, , saltHex, hashHex] = stored.split("$");
  if (scheme !== "scrypt") return false;
  const candidate = Buffer.from(hashPassword(password, saltHex).split("$")[3], "hex");
  const expected = Buffer.from(hashHex, "hex");
  return candidate.length === expected.length && timingSafeEqual(candidate, expected);
}

// Fixed salt keeps the lesson reproducible; use a fresh random salt per user in real systems.
const saltHex = "a1b2c3d4e5f60718293a4b5c6d7e8f90";
const stored = hashPassword("correct horse", saltHex);
assert.ok(stored.startsWith("scrypt$16384$"));
assert.ok(!stored.includes("correct horse"));
assert.equal(verifyPassword("correct horse", stored), true);
assert.equal(verifyPassword("wrong horse", stored), false);
const rehashed = hashPassword("correct horse", "ffffffffffffffffffffffffffffffff");
assert.ok(rehashed !== stored);
const sessions = new Map();
const token = `sess_${stored.slice(-12)}`;
sessions.set(token, { userId: "u-1", expiresAt: 1700000600 });
const session = sessions.get(token);
assert.equal(session.userId, "u-1");
assert.equal(session.expiresAt > 1700000000, true);
console.log("scheme: scrypt cost N: 16384 hash bytes:", stored.split("$")[3].length / 2);
console.log("verify correct:", verifyPassword("correct horse", stored));
console.log("verify wrong:", verifyPassword("wrong horse", stored));
console.log("new salt -> new hash:", rehashed !== stored);

