import assert from "node:assert/strict";
import { createHmac } from "node:crypto";

const SECRET = "lesson-secret-rotate-me";

function sign(payload) {
  const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })).toString("base64url");
  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const signature = createHmac("sha256", SECRET).update(`${header}.${body}`).digest("base64url");
  return `${header}.${body}.${signature}`;
}

function verify(token, now, revoked) {
  const [header, body, signature] = token.split(".");
  const expected = createHmac("sha256", SECRET).update(`${header}.${body}`).digest("base64url");
  if (signature !== expected) return { ok: false, reason: "bad-signature" };
  const payload = JSON.parse(Buffer.from(body, "base64url").toString("utf8"));
  if (revoked && revoked.has(payload.jti)) return { ok: false, reason: "revoked" };
  if (now >= payload.exp) return { ok: false, reason: "expired" };
  return { ok: true, payload };
}

const now = 1700000000;
const access = sign({ sub: "user-1", jti: "j-1", iat: now, exp: now + 600, scope: "todos:read" });
const fresh = verify(access, now);
assert.equal(fresh.ok, true);
assert.equal(fresh.payload.scope, "todos:read");
const tampered = access.slice(0, -1) + (access.endsWith("A") ? "B" : "A");
assert.equal(verify(tampered, now).reason, "bad-signature");
const revoked = new Set(["j-1"]);
assert.equal(verify(access, now, revoked).reason, "revoked");
assert.equal(verify(access, now + 601).reason, "expired");
const [h, b, s] = access.split(".");
console.log("header:", Buffer.from(h, "base64url").toString("utf8"));
console.log("payload:", Buffer.from(b, "base64url").toString("utf8"));
console.log("signature bytes:", Buffer.from(s, "base64url").length);
console.log("fresh verify ok:", fresh.ok);
console.log("tampered:", verify(tampered, now).reason, "| revoked:", verify(access, now, revoked).reason, "| expired:", verify(access, now + 601).reason);

