import assert from "node:assert/strict";

const PERMISSIONS = {
  viewer: ["todos:read"],
  editor: ["todos:read", "todos:create", "todos:update"],
  admin: ["todos:read", "todos:create", "todos:update", "todos:delete"],
};

function can(user, action) {
  return PERMISSIONS[user.role]?.includes(action) ?? false;
}

function authorizeUpdate(user, todo) {
  if (!user) return 401;
  if (!can(user, "todos:update")) return 403;
  if (todo.ownerId !== user.id) return 404;
  return 200;
}

const todo = { id: 7, ownerId: "u-1", title: "Ship" };
assert.equal(authorizeUpdate({ id: "u-1", role: "editor" }, todo), 200);
assert.equal(authorizeUpdate({ id: "u-2", role: "editor" }, todo), 404);
assert.equal(authorizeUpdate({ id: "u-2", role: "viewer" }, todo), 403);
assert.equal(authorizeUpdate(null, todo), 401);
assert.equal(authorizeUpdate({ id: "u-2", role: "admin" }, todo), 404);
assert.equal(can({ role: "admin" }, "todos:delete"), true);
assert.equal(can({ role: "editor" }, "todos:delete"), false);
console.log("editor own update:", authorizeUpdate({ id: "u-1", role: "editor" }, todo));
console.log("editor foreign update:", authorizeUpdate({ id: "u-2", role: "editor" }, todo));
console.log("viewer update:", authorizeUpdate({ id: "u-2", role: "viewer" }, todo));
console.log("guest:", authorizeUpdate(null, todo));
console.log("admin foreign update:", authorizeUpdate({ id: "u-2", role: "admin" }, todo));

