import assert from "node:assert/strict";

function sessionCookie(token, maxAgeSeconds = 3600) {
  return `sid=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAgeSeconds}`;
}

function parseCookie(header) {
  const jar = {};
  for (const part of (header ?? "").split(";")) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    jar[part.slice(0, index).trim()] = part.slice(index + 1).trim();
  }
  return jar;
}

function requestAllowed(cookieHeader, { crossSite = false, method = "GET" } = {}) {
  const sid = parseCookie(cookieHeader).sid;
  if (!sid) return { allowed: false, reason: "no-session" };
  if (crossSite && method !== "GET") return { allowed: false, reason: "samesite-lax-blocks-cross-site-post" };
  return { allowed: true };
}

