assert.deepEqual(requestAllowed("sid=abc"), { allowed: true });
assert.deepEqual(requestAllowed(""), { allowed: false, reason: "no-session" });
assert.deepEqual(requestAllowed("sid=abc", { crossSite: true, method: "POST" }), { allowed: false, reason: "samesite-lax-blocks-cross-site-post" });
assert.deepEqual(requestAllowed("sid=abc", { crossSite: true, method: "GET" }), { allowed: true });
