import assert from "node:assert/strict";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = "form-secret-rotate-me";

function csrfToken(sessionId) {
  return createHmac("sha256", SECRET).update(sessionId).digest("base64url");
}

function checkCsrf(sessionId, headerToken, cookieToken) {
  if (!headerToken || !cookieToken || headerToken !== cookieToken) return false;
  const expected = csrfToken(sessionId);
  return headerToken.length === expected.length
    && timingSafeEqual(Buffer.from(headerToken), Buffer.from(expected));
}

function escapeHtml(text) {
  return text.replace(/[&<>"']/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]);
}

const token = csrfToken("session-1");
assert.equal(checkCsrf("session-1", token, token), true);
assert.equal(checkCsrf("session-1", token, "other-token"), false);
assert.equal(checkCsrf("session-2", token, token), false);
assert.equal(checkCsrf("session-1", "", token), false);
assert.equal(escapeHtml("<script>alert(1)</script>"), "&lt;script&gt;alert(1)&lt;/script&gt;");
assert.equal(escapeHtml('she said "hi" & left'), "she said &quot;hi&quot; &amp; left");
const comment = '<img src=x onerror="steal()">';
console.log("csrf valid:", checkCsrf("session-1", token, token));
console.log("cookie/header mismatch rejected:", checkCsrf("session-1", token, "other-token"));
console.log("foreign session rejected:", checkCsrf("session-2", token, token));
console.log("escaped:", escapeHtml(comment));

