  { id: 3, name: "root", role: "admin" },
];

function concatSelect(name) {
  return `SELECT * FROM users WHERE name = '${name}'`;
}

// Mock executor: understands only `... WHERE name = '<literal>'` and the
// tautology `... OR '<a>' = '<a>'` — enough to demonstrate the failure mode.
function runConcat(sql) {
  const simple = sql.match(/^SELECT \* FROM users WHERE name = '([^']*)'$/);
  if (simple) return table.filter(u => u.name === simple[1]);
  const tautology = sql.match(/^SELECT \* FROM users WHERE name = '([^']*)' OR '([^']*)' = '([^']*)'$/);
  if (tautology && tautology[2] === tautology[3]) return [...table];
  throw new Error("parse error");
}

function runParameterized(name) {
  return table.filter(u => u.name === name);
}

const attack = "Bob' OR '1' = '1";
const vulnerableSql = concatSelect(attack);
assert.equal(runConcat(vulnerableSql).length, 3);
assert.equal(runParameterized(attack).length, 0);
assert.equal(runConcat(concatSelect("Ada")).length, 1);
assert.equal(runParameterized("Ada").length, 1);
const stacked = concatSelect("x'; DROP TABLE users; --");
let stackedResult;
try { runConcat(stacked); } catch (error) { stackedResult = error.message; }
assert.equal(stackedResult, "parse error");
console.log("injected SQL:", vulnerableSql);
console.log("vulnerable rows returned:", runConcat(vulnerableSql).length);
console.log("parameterized rows returned:", runParameterized(attack).length);
console.log("legit parameterized rows:", runParameterized("Ada").length);
console.log("stacked statement in mock:", stackedResult);

