const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
const FIXED_TS = "2026-10-23T10:00:00Z";

function createLogger({ minLevel = "info", sink }) {
  const min = LEVELS[minLevel];
  return (level, requestId, message, fields = {}) => {
    if (LEVELS[level] < min) return;
    sink.push({ ts: FIXED_TS, level, requestId, message, ...fields });
  };
}

