import assert from "node:assert/strict";

function fixedWindow({ limit, windowMs }) {
  const buckets = new Map();
  return function check(key, now) {
    const bucket = buckets.get(key);
    if (!bucket || now >= bucket.resetAt) {
      buckets.set(key, { count: 1, resetAt: now + windowMs });
      return { allowed: true, remaining: limit - 1 };
    }
    bucket.count += 1;
    if (bucket.count > limit) return { allowed: false, retryAfterMs: bucket.resetAt - now };
    return { allowed: true, remaining: limit - bucket.count };
  };
}

const limiter = fixedWindow({ limit: 3, windowMs: 60000 });
const t0 = 1000;
assert.deepEqual(limiter("user-1", t0), { allowed: true, remaining: 2 });
assert.deepEqual(limiter("user-1", t0 + 1), { allowed: true, remaining: 1 });
assert.deepEqual(limiter("user-1", t0 + 2), { allowed: true, remaining: 0 });
const blocked = limiter("user-1", t0 + 3);
assert.equal(blocked.allowed, false);
assert.equal(blocked.retryAfterMs, 59997);
const other = limiter("user-2", t0);
assert.equal(other.allowed, true);
const afterWindow = limiter("user-1", t0 + 60000);
assert.equal(afterWindow.allowed, true);
console.log("blocked response:", JSON.stringify({ status: 429, retryAfterSec: Math.ceil(blocked.retryAfterMs / 1000) }));
console.log("other user allowed:", other.allowed);
console.log("same user after window:", afterWindow.allowed);

