import assert from "node:assert/strict";
import { createHash } from "node:crypto";

const etagOf = value => `"${createHash("sha256").update(JSON.stringify(value)).digest("hex").slice(0, 12)}"`;

function createCache() {
  const entries = new Map();
  return {
    get(key, ifNoneMatch) {
      const entry = entries.get(key);
      if (!entry) return { status: "miss" };
      if (ifNoneMatch && ifNoneMatch === entry.etag) return { status: "revalidated" };
      return { status: "hit", value: entry.value, etag: entry.etag };
    },
    put(key, value) { entries.set(key, { value, etag: etagOf(value) }); },
    invalidate(key) { entries.delete(key); },
  };
}

const cache = createCache();
assert.equal(cache.get("todo:1").status, "miss");
cache.put("todo:1", { id: 1, title: "Old" });
const first = cache.get("todo:1");
assert.equal(first.status, "hit");
assert.equal(cache.get("todo:1", first.etag).status, "revalidated");
cache.put("todo:1", { id: 1, title: "New" });
const afterWrite = cache.get("todo:1", first.etag);
assert.equal(afterWrite.status, "hit");
assert.equal(afterWrite.etag !== first.etag, true);
assert.equal(afterWrite.value.title, "New");
cache.invalidate("todo:1");
assert.equal(cache.get("todo:1", first.etag).status, "miss");
console.log("first etag:", first.etag, "status:", first.status);
console.log("client revalidates with same etag -> revalidated");
console.log("after write etag changed:", afterWrite.etag, "-> fresh copy served");
console.log("after invalidation -> miss");

