import assert from "node:assert/strict";

function createDb() {
  const accounts = new Map([["a", 100], ["b", 50]]);
  const todos = [];
  let txCounter = 0;
  return {
    accounts,
    todos,
    transaction(operations) {
      const txId = ++txCounter;
      const snapshotAccounts = new Map(accounts);
      const snapshotTodos = [...todos];
      try {
        for (const operation of operations) operation();
        return { committed: true, txId };
      } catch (error) {
        accounts.clear();
        for (const [key, value] of snapshotAccounts) accounts.set(key, value);
        todos.length = 0;
        todos.push(...snapshotTodos);
        return { committed: false, txId, rolledBack: error.message };
      }
    },
  };
}

function transfer(db, from, to, amount) {
  return db.transaction([
    () => {
      if (db.accounts.get(from) < amount) throw new Error("insufficient funds");
      db.accounts.set(from, db.accounts.get(from) - amount);
    },
    () => db.accounts.set(to, db.accounts.get(to) + amount),
  ]);
}

const db = createDb();
const ok = transfer(db, "a", "b", 30);
assert.equal(ok.committed, true);
assert.equal(db.accounts.get("a"), 70);
assert.equal(db.accounts.get("b"), 80);
const fail = transfer(db, "a", "b", 999);
assert.equal(fail.committed, false);
assert.equal(fail.rolledBack, "insufficient funds");
assert.equal(db.accounts.get("a"), 70);
assert.equal(db.accounts.get("b"), 80);
console.log(JSON.stringify(ok), JSON.stringify(fail));
console.log("balances after failure:", db.accounts.get("a"), db.accounts.get("b"));

