// Mock "database" of user rows. Old shape: { id, name }. New shape: { id, fullName }.
function migrate(db, from, to) {
  if (from === 1 && to === 2) {
    for (const row of db.users) row.fullName = row.name;
    db.schema = 2;
    db.readColumn = "name";
    return { step: "expand+backfill", rows: db.users.length };
  }
  if (from === 2 && to === 3) {
    db.readColumn = "fullName";
    return { step: "switch-reads", rows: db.users.length };
  }
  if (from === 3 && to === 4) {
    for (const row of db.users) delete row.name;
    db.schema = 4;
    db.readColumn = "fullName";
    return { step: "contract", rows: db.users.length };
  }
  throw new Error(`unsupported migration ${from}->${to}`);
}

function readUsers(db) {
  return db.users.map(row => row[db.readColumn]);
}

const db = { schema: 1, readColumn: "name", users: [{ id: 1, name: "Ada" }, { id: 2, name: "Bob" }] };
const step1 = migrate(db, 1, 2);
const afterExpand = JSON.stringify(db.users[1]);
assert.deepEqual(readUsers(db), ["Ada", "Bob"]);
assert.ok(db.users.every(row => row.fullName === row.name));
const step2 = migrate(db, 2, 3);
assert.deepEqual(readUsers(db), ["Ada", "Bob"]);
const step3 = migrate(db, 3, 4);
assert.deepEqual(readUsers(db), ["Ada", "Bob"]);
assert.ok(db.users.every(row => !("name" in row)));
assert.throws(() => migrate(db, 1, 4), /unsupported/);
console.log(step1.step, "->", afterExpand);
console.log(step2.step, "reads:", readUsers(db).join(","));
console.log(step3.step, "old column present:", "name" in db.users[0]);

