import assert from "node:assert/strict";

const SPEC = {
  PORT: { type: "port", required: true },
  DATABASE_URL: { type: "string", required: true },
  NODE_ENV: { type: "enum", values: ["development", "test", "production"], default: "development" },
  RATE_LIMIT: { type: "integer", required: false, default: 100 },
};

function loadConfig(env) {
  const config = {};
  const problems = [];
  for (const [key, rule] of Object.entries(SPEC)) {
    const raw = env[key];
    if (raw === undefined || raw === "") {
      if (rule.default !== undefined) { config[key] = rule.default; continue; }
      if (rule.required) { problems.push(`${key} is required`); continue; }
    }
    if (rule.type === "port") {
      const port = Number(raw);
      if (!Number.isInteger(port) || port < 1 || port > 65535) { problems.push(`${key} must be an integer port 1-65535, got "${raw}"`); continue; }
      config[key] = port;
    } else if (rule.type === "integer") {
      const value = Number(raw);
      if (!Number.isInteger(value)) { problems.push(`${key} must be an integer, got "${raw}"`); continue; }
      config[key] = value;
    } else if (rule.type === "enum") {
      if (!rule.values.includes(raw)) { problems.push(`${key} must be one of ${rule.values.join("|")}, got "${raw}"`); continue; }
      config[key] = raw;
    } else {
      config[key] = raw;
    }
  }
  if (problems.length > 0) {
    const error = new Error(`Invalid configuration:\n- ${problems.join("\n- ")}`);
    error.problems = problems;
    throw error;
  }
  return config;
}

const good = loadConfig({ PORT: "3000", DATABASE_URL: "postgres://localhost/app", RATE_LIMIT: "50" });
assert.equal(good.PORT, 3000);
assert.equal(good.NODE_ENV, "development");
assert.equal(good.RATE_LIMIT, 50);
let failure;
try { loadConfig({ PORT: "http", DATABASE_URL: "" }); } catch (error) { failure = error; }
assert.ok(failure.problems.some(p => p.startsWith("PORT")));
assert.ok(failure.problems.some(p => p.startsWith("DATABASE_URL")));
console.log(good.PORT, good.NODE_ENV, good.RATE_LIMIT);
console.log(failure.problems.join(" | "));

