// Mock dependency: honors cancellation and reports whether it finished its work.
function mockFetch(latencyMs, value) {
  const job = { finished: false, cancelled: false };
  job.run = signal => new Promise((resolve, reject) => {
    if (signal?.aborted) { job.cancelled = true; reject(signal.reason); return; }
    const timer = setTimeout(() => { job.finished = true; resolve(value); }, latencyMs);
    signal?.addEventListener("abort", () => { clearTimeout(timer); job.cancelled = true; reject(signal.reason); }, { once: true });
  });
  return job;
}

async function fetchWithTimeout(doFetch, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error(`timeout after ${timeoutMs}ms`)), timeoutMs);
  try {
    return await doFetch(controller.signal);
  } finally {
    clearTimeout(timer);
  }
}

