import assert from "node:assert/strict";

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function isRetryable(error) {
  return error?.retryable === true;
}

async function retry(operation, { attempts = 4, baseDelayMs = 5, factor = 2 } = {}) {
  const delays = [];
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return { ok: true, value: await operation(attempt), attempts: attempt, delays };
    } catch (error) {
      lastError = error;
      if (!isRetryable(error) || attempt === attempts) break;
      const delay = baseDelayMs * factor ** (attempt - 1);
      delays.push(delay);
      await sleep(delay);
    }
  }
  return { ok: false, error: lastError.message, attempts, delays };
}

let calls = 0;
const flaky = async () => {
  calls++;
  if (calls < 3) { const error = new Error("upstream 503"); error.retryable = true; throw error; }
  return "data-1";
};
const result = await retry(flaky);
assert.equal(result.ok, true);
assert.equal(result.value, "data-1");
assert.equal(result.attempts, 3);
assert.deepEqual(result.delays, [5, 10]);

let fatalCalls = 0;
const fatal = async () => {
  fatalCalls++;
  const error = new Error("validation rejected"); error.retryable = false; throw error;
};
const fatalResult = await retry(fatal, { attempts: 4 });
assert.equal(fatalResult.ok, false);
assert.equal(fatalCalls, 1);
assert.deepEqual(fatalResult.delays, []);

const exhausted = await retry(async () => { const error = new Error("down"); error.retryable = true; throw error; }, { attempts: 3 });
assert.equal(exhausted.ok, false);
assert.deepEqual(exhausted.delays, [5, 10]);
console.log("success attempts:", result.attempts, "backoffs(ms):", result.delays.join(","));
console.log("fatal attempts:", fatalCalls, "backoffs(ms):", fatalResult.delays.length);
console.log("exhausted:", exhausted.ok, "error:", exhausted.error, "backoffs(ms):", exhausted.delays.join(","));

