import assert from "node:assert/strict";

function createBreaker({ failureThreshold = 3, resetAfterMs = 1000 } = {}) {
  let state = "closed";
  let failures = 0;
  let openedAt = null;
  return {
    get state() { return state; },
    async call(operation, now = 0) {
      if (state === "open") {
        if (now - openedAt < resetAfterMs) {
          const error = new Error("circuit open");
          error.fastFail = true;
          throw error;
        }
        state = "half-open";
      }
      try {
        const value = await operation();
        failures = 0;
        state = "closed";
        return value;
      } catch (error) {
        failures += 1;
        if (state === "half-open" || failures >= failureThreshold) {
          state = "open";
          openedAt = now;
        }
        throw error;
      }
    },
  };
}

const breaker = createBreaker({});
const failing = async () => { throw new Error("dependency down"); };
let lastError;
for (let i = 1; i <= 3; i++) {
  try { await breaker.call(failing, i * 10); } catch (error) { lastError = error; }
}
assert.equal(lastError.message, "dependency down");
console.log("after 3 failures state:", breaker.state);
let fastFail;
try { await breaker.call(failing, 500); } catch (error) { fastFail = error; }
assert.equal(fastFail.fastFail, true);
console.log("call at t=500:", fastFail.message, "(dependency not called)");
const probe = await breaker.call(async () => "recovered", 1100);
assert.equal(probe, "recovered");
console.log("probe at t=1100:", probe, "state:", breaker.state);

