import assert from "node:assert/strict";

function createQueue({ maxAttempts = 3 } = {}) {
  const pending = [];
  const dead = [];
  const processed = [];
  return {
    pending, dead, processed,
    push(job) { pending.push({ ...job, attempts: 0 }); },
    async drain(handle) {
      while (pending.length > 0) {
        const job = pending.shift();
        job.attempts += 1;
        try {
          await handle(job);
          processed.push({ id: job.id, attempts: job.attempts });
        } catch (error) {
          if (job.attempts >= maxAttempts) dead.push({ id: job.id, error: error.message, attempts: job.attempts });
          else pending.push(job);
        }
      }
    },
  };
}

const queue = createQueue({ maxAttempts: 3 });
queue.push({ id: "email-1" });
queue.push({ id: "email-2" });
queue.push({ id: "email-3" });
const failAlways = new Set(["email-3"]);
const attemptsPerJob = {};
await queue.drain(async job => {
  attemptsPerJob[job.id] = (attemptsPerJob[job.id] ?? 0) + 1;
  if (failAlways.has(job.id)) throw new Error("smtp unavailable");
});
assert.equal(queue.processed.length, 2);
assert.equal(queue.dead.length, 1);
assert.deepEqual(queue.dead[0], { id: "email-3", error: "smtp unavailable", attempts: 3 });
assert.equal(attemptsPerJob["email-3"], 3);
assert.deepEqual(queue.pending, []);
console.log("processed:", queue.processed.map(job => job.id).join(","));
console.log("dead letter:", JSON.stringify(queue.dead[0]));
console.log("pending left:", queue.pending.length);

