function createMetrics() {
  const counters = new Map();
  return {
    increment(name, labels = "", by = 1) {
      const key = `${name}{${labels}}`;
      counters.set(key, (counters.get(key) ?? 0) + by);
    },
    snapshot() {
      return Object.fromEntries([...counters.entries()].sort());
    },
  };
}

