import assert from "node:assert/strict";
import { createServer } from "node:http";

function createApp(store) {
  return createServer(async (request, response) => {
    const reply = (status, body, headers = {}) => {
      response.writeHead(status, { "Content-Type": "application/json", ...headers });
      response.end(body === undefined ? undefined : JSON.stringify(body));
    };
    const url = new URL(request.url, "http://localhost");
    if (url.pathname !== "/notes") return reply(404, { error: "not found" });
    if (request.method === "GET") {
      const owner = url.searchParams.get("owner");
      return reply(200, store.notes.filter(note => !owner || note.owner === owner));
    }
    if (request.method === "POST") {
      const chunks = [];
      for await (const chunk of request) chunks.push(chunk);
      let body;
      try { body = JSON.parse(Buffer.concat(chunks).toString("utf8")); } catch { return reply(400, { error: "invalid json" }); }
      if (!body || typeof body !== "object" || Array.isArray(body)) return reply(400, { error: "invalid body" });
      if (Object.keys(body).some(key => key !== "title" && key !== "owner")) return reply(400, { error: "unexpected fields" });
      if (typeof body.title !== "string" || body.title.trim().length < 2) return reply(400, { error: "invalid title" });
      const note = { id: store.next++, title: body.title.trim(), owner: body.owner ?? "anon" };
      store.notes.push(note);
      return reply(201, note, { Location: `/notes/${note.id}` });
    }
    response.setHeader("Allow", "GET, POST");
    return reply(405, { error: "method not allowed" });
  });
}

const store = { next: 1, notes: [] };
const server = createApp(store);
server.requestTimeout = 2000;
server.headersTimeout = 2000;
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
const base = `http://127.0.0.1:${server.address().port}`;
try {
  let res = await fetch(`${base}/notes`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), []);
  res = await fetch(`${base}/notes`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: "Plan sprint" }) });
  assert.equal(res.status, 201);
  assert.equal(res.headers.get("location"), "/notes/1");
  await fetch(`${base}/notes`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ title: "Write tests", owner: "qa" }) });
  res = await fetch(`${base}/notes?owner=qa`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), [{ id: 2, title: "Write tests", owner: "qa" }]);
  res = await fetch(`${base}/notes`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" });
  assert.equal(res.status, 400);
  res = await fetch(`${base}/notes`, { method: "PUT" });
  assert.equal(res.status, 405);
  assert.equal(store.notes.length, 2);
  console.log(`integration suite passed: ${store.notes.length} notes, 6 checks`);
} finally {
  await new Promise((resolve, reject) => server.close(error => (error ? reject(error) : resolve())));
}

