function createService({ repository, fallback } = {}) {
  return {
    async getProfile(id) {
      try {
        return { source: "repository", profile: await repository.findById(id) };
      } catch (error) {
        if (fallback !== undefined) return { source: "fallback", profile: fallback };
        throw error;
      }
    },
  };
}

const healthyRepo = { findById: async id => ({ id, name: "Ada" }) };
const brokenRepo = { findById: async () => { throw new Error("connection refused"); } };

