import assert from "node:assert/strict";

function createRepo() {
  const users = new Map([[1, "Ada"], [2, "Bob"], [3, "Cydia"]]);
  const todos = [
    { id: 1, ownerId: 1, title: "t1" },
    { id: 2, ownerId: 1, title: "t2" },
    { id: 3, ownerId: 2, title: "t3" },
    { id: 4, ownerId: 3, title: "t4" },
  ];
  const stats = { userLookups: 0, batchCalls: 0 };
  return {
    stats,
    async findUser(id) { stats.userLookups++; return { id, name: users.get(id) }; },
    async findUsers(ids) { stats.batchCalls++; return ids.map(id => ({ id, name: users.get(id) })); },
    allTodos: () => [...todos],
  };
}

async function renderWithNPlusOne(repo) {
  const lines = [];
  for (const todo of repo.allTodos()) {
    const user = await repo.findUser(todo.ownerId);
    lines.push(`${todo.title} by ${user.name}`);
  }
  return lines;
}

async function renderWithBatch(repo) {
  const todos = repo.allTodos();
  const uniqueIds = [...new Set(todos.map(t => t.ownerId))];
  const users = await repo.findUsers(uniqueIds);
  const namesById = new Map(users.map(u => [u.id, u.name]));
  return todos.map(t => `${t.title} by ${namesById.get(t.ownerId)}`);
}

const repoSlow = createRepo();
const slow = await renderWithNPlusOne(repoSlow);
const repoFast = createRepo();
const fast = await renderWithBatch(repoFast);
assert.deepEqual(slow, fast);
assert.equal(repoSlow.stats.userLookups, 4);
assert.equal(repoFast.stats.batchCalls, 1);
assert.equal(repoFast.stats.userLookups, 0);
console.log(slow.join(" | "));
console.log("N+1 queries:", repoSlow.stats.userLookups, "batch queries:", repoFast.stats.batchCalls);

