import assert from "node:assert/strict";

function createNode({ sharedSessions = null } = {}) {
  const local = new Map();
  return {
    handle(token, userId) {
      const store = sharedSessions ?? local;
      if (!store.has(token)) store.set(token, { userId });
      return store.get(token).userId;
    },
    get localSessionCount() { return local.size; },
  };
}

function roundRobin(nodes) {
  let index = 0;
  return () => nodes[index++ % nodes.length];
}

const token = "sess-1";
const localNodes = [createNode(), createNode()];
const nextLocal = roundRobin(localNodes);
const localResults = [nextLocal().handle(token, "u-1"), nextLocal().handle(token, "u-1")];
const duplicated = localNodes.reduce((sum, node) => sum + node.localSessionCount, 0);
assert.equal(duplicated, 2);

const shared = new Map();
const sharedNodes = [createNode({ sharedSessions: shared }), createNode({ sharedSessions: shared })];
const nextShared = roundRobin(sharedNodes);
const sharedResults = [nextShared().handle(token, "u-1"), nextShared().handle(token, "u-1")];
assert.deepEqual(sharedResults, ["u-1", "u-1"]);
assert.equal(shared.size, 1);
assert.equal(sharedNodes.reduce((sum, node) => sum + node.localSessionCount, 0), 0);
console.log("round-robin responses:", localResults.join(","), "(both requests succeeded)");
console.log("sessions stored across two local-memory nodes:", duplicated, "(state duplicated)");
console.log("sessions stored with a shared store:", shared.size);

