import assert from "node:assert/strict";
import { createServer } from "node:http";

const sessions = new Map([["learn-token", { userId: "u-1" }]]);
const todos = [];
const buckets = new Map();
const WINDOW_MS = 60000;
const LIMIT = 5;

function rateLimit(key, now) {
  const bucket = buckets.get(key);
  if (!bucket || now >= bucket.resetAt) {
    buckets.set(key, { count: 1, resetAt: now + WINDOW_MS });
    return { allowed: true };
  }
  if (bucket.count >= LIMIT) return { allowed: false, retryAfter: Math.ceil((bucket.resetAt - now) / 1000) };
  bucket.count += 1;
  return { allowed: true };
}

const server = createServer(async (request, response) => {
  const reply = (status, body = {}, headers = {}) => {
    response.writeHead(status, { "Content-Type": "application/json", ...headers });
    response.end(JSON.stringify(body));
  };
  // x-test-now is a teaching clock: a fixed value keeps the run deterministic.
  const now = Number(request.headers["x-test-now"] ?? Date.now());
  const url = new URL(request.url, "http://localhost");
  if (url.pathname !== "/todos") return reply(404, { error: "not found" });
  const authorization = request.headers.authorization ?? "";
  const session = sessions.get(authorization.replace(/^Bearer /, ""));
  if (!session) return reply(401, { error: "unauthorized" });
  const limit = rateLimit(session.userId, now);
  if (!limit.allowed) return reply(429, { error: "rate limited" }, { "Retry-After": String(limit.retryAfter) });
  if (request.method === "GET") return reply(200, todos.map(({ id, title }) => ({ id, title })));
  if (request.method === "POST") {
    const chunks = [];
    for await (const chunk of request) chunks.push(chunk);
    let body;
    try { body = JSON.parse(Buffer.concat(chunks).toString("utf8")); } catch { return reply(400, { error: "invalid json" }); }
    const valid = body && typeof body === "object" && !Array.isArray(body)
      && Object.keys(body).every(key => key === "title")
      && typeof body.title === "string" && body.title.trim().length >= 2 && body.title.trim().length <= 80;
    if (!valid) return reply(400, { error: "invalid title" });
    const todo = { id: todos.length + 1, title: body.title.trim(), ownerId: session.userId };
    todos.push(todo);
    return reply(201, { id: todo.id, title: todo.title });
  }
  response.setHeader("Allow", "GET, POST");
  return reply(405, { error: "method not allowed" });
});

server.requestTimeout = 2000;
server.headersTimeout = 2000;
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
const base = `http://127.0.0.1:${server.address().port}`;
const auth = { "content-type": "application/json", authorization: "Bearer learn-token", "x-test-now": "1000" };
try {
  let res = await fetch(`${base}/nope`, { headers: { "x-test-now": "1000" } });
  assert.equal(res.status, 404);
  console.log("guest GET /nope -> 404");
  res = await fetch(`${base}/todos`, { method: "POST", headers: { "x-test-now": "1000" }, body: "{}" });
  assert.equal(res.status, 401);
  console.log("guest POST /todos -> 401");
  res = await fetch(`${base}/todos`, { method: "POST", headers: auth, body: '{"title":"x"}' });
  assert.equal(res.status, 400);
  console.log("u-1 POST invalid title -> 400");
  for (const title of ["  Read HTTP  ", "Write tests", "Ship release"]) {
    res = await fetch(`${base}/todos`, { method: "POST", headers: auth, body: JSON.stringify({ title }) });
    assert.equal(res.status, 201);
    console.log("u-1 POST -> 201", JSON.stringify(await res.json()));
  }
  res = await fetch(`${base}/todos`, { headers: auth });
  assert.equal(res.status, 200);
  const list = await res.json();
  assert.equal(list.length, 3);
  console.log("u-1 GET -> 200", JSON.stringify(list));
  res = await fetch(`${base}/todos`, { method: "POST", headers: auth, body: JSON.stringify({ title: "Blocked" }) });
  assert.equal(res.status, 429);
  assert.equal(res.headers.get("retry-after"), "60");
  console.log(`u-1 POST -> 429 retry-after ${res.headers.get("retry-after")}s`);
  assert.equal(todos.length, 3);
  assert.ok(todos.every(t => t.ownerId === "u-1"));
} finally {
  await new Promise((resolve, reject) => server.close(error => (error ? reject(error) : resolve())));
}

